const API_BASE = "/api";

export async function generateAssessment(course) {
  const res = await fetch(`${API_BASE}/assessment/generate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ course }),
  });
  return res.json();
}

export async function checkAssessment(course, answers) {
  const res = await fetch(`${API_BASE}/assessment/check`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ course, answers }),
  });
  return res.json();
}

export async function checkSimilarity(course, file) {
  const formData = new FormData();
  formData.append("course", course);
  formData.append("file", file);

  const res = await fetch(`${API_BASE}/similarity/check`, {
    method: "POST",
    body: formData,
  });
  return res.json();
}
